#!/usr/bin/env bash
# Run every CI check locally. Generated by aurora@aurora-smart-home (ha-integration-dev skill)
# https://github.com/tonylofgren/aurora-smart-home
set -euo pipefail
cd "$(dirname "$0")/.."

echo "== ruff";          ruff check . && ruff format --check .
echo "== mypy";          mypy
echo "== translations";  python3 scripts/check_translations.py
echo "== consistency";   python3 scripts/check_consistency.py
echo "== private data";  python3 scripts/check_private_data.py --base "${BASE:-HEAD}"
echo "== tests";         python3 -m pytest -q --cov=custom_components/storage_manager --cov-branch --cov-report=xml
echo "== coverage";      python3 scripts/check_coverage_per_module.py coverage.xml
if command -v npm >/dev/null; then
  echo "== panel build"
  (cd frontend && npm ci --silent && npm run build --silent)
  git diff --exit-code -- custom_components/storage_manager/frontend/
fi
echo "All checks passed."
